        'duplicate|json' = @{ Bytes=5691; Hash='39476f32fd8cd353aa2a4934ab6c42d711a9e5dd8c49e50476322e181c0d69bf' }
        'duplicate|markdown' = @{ Bytes=711; Hash='7accb4e32529e551d936cb9b82f24edec28cc2d332bc10e90b0b4be91db06f8a' }
        'parse-failure|json' = @{ Bytes=5581; Hash='0e2d19aa0d153a5a3c3873ce639ebc07df946f92a014a2b29d174a3079ae24b6' }
        'parse-failure|markdown' = @{ Bytes=715; Hash='a3b03b5f2d674984e5c3227764300ce6b2c516910e0cc43a039befc6eb0b25ce' }
    }
    $baselineReports = @{}
    $baselineExits = @{}
    $matched = 0
    foreach ($variant in @('baseline','candidate')) {
        if ($variant -eq 'candidate') {
            [IO.File]::WriteAllBytes($action,[IO.File]::ReadAllBytes($candidateAction))
            $helper = Join-Path $repo $helperPath
            [IO.File]::WriteAllBytes($helper,[IO.File]::ReadAllBytes($candidateHelper))
            $writtenAction = git -C $checkout hash-object --no-filters -- $action
            if ($LASTEXITCODE -ne 0 -or $writtenAction -cne $candidateActionBlob) { throw 'Candidate action copy mismatch' }
            $writtenHelper = git -C $checkout hash-object --no-filters -- $helper
            if ($LASTEXITCODE -ne 0 -or $writtenHelper -cne $candidateHelperBlob) { throw 'Candidate helper copy mismatch' }
        }
        $variantExits = @{}
        $completed = 0
        foreach ($case in @('clean','duplicate','parse-failure')) {
            [IO.File]::WriteAllBytes($first,$firstBytes)
            [IO.File]::WriteAllBytes($second,$secondBytes)
            if ($case -eq 'duplicate') {
                $seedText = "`nfunction $seed { 'synthetic-parity' }`n"
                [IO.File]::AppendAllText($first,$seedText,[Text.UTF8Encoding]::new($false))
                [IO.File]::AppendAllText($second,$seedText,[Text.UTF8Encoding]::new($false))
            } elseif ($case -eq 'parse-failure') {
                [IO.File]::AppendAllText($first,"`nfunction $parseSeed {`n",[Text.UTF8Encoding]::new($false))
            }
            foreach ($path in @($json,$markdown)) {
                if ([IO.File]::Exists($path)) { [IO.File]::Delete($path) }
            }
            $output = @(& $pwsh -NoProfile -NonInteractive -File $action 2>&1)
            $exit = $LASTEXITCODE
            if (-not [IO.File]::Exists($json) -or -not [IO.File]::Exists($markdown)) {
                throw "Report missing in $case (exit=$exit): $($output -join ' ')"
            }
            $report = Get-Content -LiteralPath $json -Raw | ConvertFrom-Json
            if ($report.schema_version -ne 'dcoir_powershell_duplicate_function_report_v1' -or $report.summary.file_count -ne ($parts.Count + 1)) { throw "Report schema or target count mismatch: $case" }
            $dup = [int]$report.summary.duplicate_function_count
            $parse = [int]$report.summary.parse_failure_count
            if ($case -eq 'clean') {
                if ($exit -ne 0 -or $dup -ne 0 -or $parse -ne 0 -or -not $report.validation.success) { throw 'Clean baseline failed' }
            } elseif ($case -eq 'duplicate') {
                $seeded = @($report.duplicates | Where-Object { $_.function_name -eq $seed })
                if ($exit -ne 0 -or $dup -ne 1 -or $parse -ne 0 -or -not $report.validation.success -or $seeded.Count -ne 1 -or $seeded[0].occurrence_count -ne 2) { throw 'Seeded duplicate baseline failed' }
            } else {
                if ($exit -ne 1 -or $dup -ne 0 -or $parse -ne 1 -or $report.validation.success) { throw 'Seeded parser-failure baseline failed' }
            }
            Write-Output "SCENARIO variant=$variant case=$case exit=$exit files=$($report.summary.file_count) duplicates=$dup parse_failures=$parse validation_success=$($report.validation.success)"
            $variantExits[$case] = $exit
            foreach ($kind in @('json','markdown')) {
                $reportPath = if ($kind -eq 'json') { $json } else { $markdown }
                $key = "$case|$kind"
                $bytes = [IO.File]::ReadAllBytes($reportPath)
                $hash = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($bytes)).ToLowerInvariant()
                $prior = $priorEvidence[$key]
                if ($bytes.Length -ne $prior.Bytes -or $hash -cne $prior.Hash) { throw "Report differs from prior immutable baseline: $variant $key bytes=$($bytes.Length) sha256=$hash" }
                $encoded = [Convert]::ToBase64String($bytes)
                if ($variant -eq 'baseline') { $baselineReports[$key] = $encoded }
                else {
                    if ($encoded -cne $baselineReports[$key] -or $exit -ne $baselineExits[$case]) { throw "Same-run report/exit parity failed: $key" }
                    Write-ReportEvidence $case $kind $reportPath
                    Write-Output "BYTE_PARITY_PASS case=$case kind=$kind bytes=$($bytes.Length) sha256=$hash exit=$exit"
                    $matched++
                }
            }
            $completed++
        }
        if ($completed -ne 3 -or $variantExits.Count -ne 3) { throw "Scenario count mismatch: $variant" }
        if ($variant -eq 'baseline') { $baselineExits = $variantExits }
    }
    if ($matched -ne 6 -or $baselineReports.Count -ne 6) { throw 'Report parity count mismatch' }
    Write-Output "REPORT_PARITY_COMPLETE scenarios=3 reports=6 baseline=$base candidate=$feature pwsh=$($PSVersionTable.PSVersion)"
} finally {
    Set-Location -LiteralPath $start
    [Environment]::SetEnvironmentVariable('DUPLICATE_FUNCTION_OUTPUT_JSON',$oldJson,'Process')
    [Environment]::SetEnvironmentVariable('DUPLICATE_FUNCTION_OUTPUT_MARKDOWN',$oldMarkdown,'Process')
    if ($owned) { Remove-Item -LiteralPath $scratch -Recurse -Force -ErrorAction Stop }
}
Write-Output 'PARITY_SCRATCH_CLEANUP_COMPLETE'
$global:LASTEXITCODE = 0
